 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
 // never overflow int64.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
-    for (int b = 0; b < 256; ++b) hist[b] = 0;
+    // Use 4 sub-histograms to break store-to-load dependencies on hot bins
+    // by distributing updates for the same bin across different arrays.
+    uint32_t sub[4][256];
+    memset(sub, 0, sizeof(sub));
+
     int64_t sum = 0;
+    const int64_t *p_in = in;
+    int64_t *p_out = out;
+
     for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+        __builtin_prefetch(p_in + i + 8, 0, 3);
+        sum += p_in[i];
+        p_out[i] = sum;
+        sub[i & 3][p_in[i] & 255]++;
+    }
+
+    // Merge sub-histograms into final histogram buffer
+    for (int b = 0; b < 256; ++b) {
+        hist[b] = (uint64_t)(sub[0][b] + sub[1][b] + sub[2][b] + sub[3][b]);
     }
